import { useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { setModel, selectModel } from '../../store/slices/uiSlice';
import { MODELS, PROVIDER_LABELS } from '../../constants/models';
import { useTheme } from '../../hooks/useTheme';

export default function ModelDropdown() {
  const dispatch   = useDispatch();
  const modelId    = useSelector(selectModel);
  const { dark, cardHex, borderHex, textHex, mutedHex, hoverHex } = useTheme();
  const [open, setOpen] = useState(false);

  const current = MODELS.find((m) => m.id === modelId);

  // Group by provider
  const groups = MODELS.reduce((acc, m) => {
    const g = PROVIDER_LABELS[m.provider] ?? m.provider;
    (acc[g] = acc[g] ?? []).push(m);
    return acc;
  }, {});

  return (
    <div style={{ position: 'relative' }}>
      <button onClick={() => setOpen((p) => !p)} style={{
        display: 'flex', alignItems: 'center', gap: 5,
        background: dark ? '#22223a' : '#e8e8ff', border: 'none',
        borderRadius: 8, padding: '5px 10px',
        fontSize: 12.5, color: textHex, cursor: 'pointer',
        fontFamily: "'DM Sans', sans-serif", transition: 'background 0.15s',
      }}>
        <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="#6366f1" strokeWidth="2"><circle cx="12" cy="12" r="3"/><path d="M19.07 4.93a10 10 0 0 1 0 14.14M4.93 4.93a10 10 0 0 0 0 14.14"/></svg>
        {current?.label ?? modelId}
        <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" style={{ transform: open ? 'rotate(180deg)' : 'none', transition: 'transform 0.2s' }}><polyline points="6 9 12 15 18 9"/></svg>
      </button>

      {open && (
        <>
          {/* Backdrop */}
          <div style={{ position: 'fixed', inset: 0, zIndex: 98 }} onClick={() => setOpen(false)}/>
          <div style={{
            position: 'absolute', bottom: 36, right: 0, zIndex: 99,
            background: cardHex, border: `1px solid ${borderHex}`,
            borderRadius: 12, overflow: 'hidden', minWidth: 220,
            boxShadow: '0 8px 32px rgba(0,0,0,0.22)', animation: 'fadeUp 0.15s ease',
          }}>
            {Object.entries(groups).map(([group, models]) => (
              <div key={group}>
                <p style={{ fontSize: 10.5, fontWeight: 600, color: mutedHex, textTransform: 'uppercase', letterSpacing: '0.07em', padding: '8px 14px 4px' }}>{group}</p>
                {models.map((m) => (
                  <div key={m.id}
                    onClick={() => { if (!m.comingSoon) { dispatch(setModel(m.id)); setOpen(false); } }}
                    style={{
                      padding: '9px 14px', fontSize: 13.5, cursor: m.comingSoon ? 'default' : 'pointer',
                      color: m.comingSoon ? mutedHex : textHex,
                      display: 'flex', alignItems: 'center', gap: 8,
                      transition: 'background 0.15s',
                      opacity: m.comingSoon ? 0.6 : 1,
                    }}
                    onMouseEnter={(e) => { if (!m.comingSoon) e.currentTarget.style.background = hoverHex; }}
                    onMouseLeave={(e) => { e.currentTarget.style.background = 'none'; }}>
                    {m.id === modelId && !m.comingSoon && (
                      <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#6366f1" strokeWidth="2.5"><polyline points="20 6 9 17 4 12"/></svg>
                    )}
                    <span style={{ marginLeft: m.id === modelId && !m.comingSoon ? 0 : 22 }}>{m.label}</span>
                    {m.comingSoon && (
                      <span style={{ marginLeft: 'auto', fontSize: 10, background: dark ? '#22223a' : '#e8e8ff', color: '#6366f1', borderRadius: 6, padding: '2px 7px', fontWeight: 600 }}>Soon</span>
                    )}
                  </div>
                ))}
              </div>
            ))}
          </div>
        </>
      )}
    </div>
  );
}
